<script setup>
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';import {echarts} from '../../config/echarts'
const props=defineProps({data:{type:Array,default:()=>[]}});const el=ref(),chart=ref();const option=computed(()=>({tooltip:{trigger:'axis',formatter:p=>{const x=props.data[p[0].dataIndex];return `${x.date}<br/>支付金额 ¥${Number(x.paidAmount).toLocaleString()}<br/>下单 ${x.orderCount} · 支付 ${x.paidOrderCount}`}},grid:{left:72,right:24,top:32,bottom:42},xAxis:{type:'category',data:props.data.map(x=>x.date.slice(5))},yAxis:{type:'log',logBase:100,name:'支付金额（元）· 每档 ×100',nameTextStyle:{fontSize:10},min:1,max:Math.pow(100,Math.max(1,Math.ceil(Math.log(Math.max(1,...props.data.map(x=>Number(x.paidAmount)||0)))/Math.log(100)))),axisLabel:{formatter:v=>v>=1e8?`${v/1e8}亿`:v>=1e4?`${v/1e4}万`:v,hideOverlap:true,margin:12},minorTick:{show:false},minorSplitLine:{show:false},splitLine:{lineStyle:{color:'rgba(59,158,255,.15)'}}},series:[{type:'bar',barWidth:18,itemStyle:{borderRadius:[9,9,2,2],color:new echarts.graphic.LinearGradient(0,0,0,1,[{offset:0,color:'#55ddf5'},{offset:1,color:'#5a7cff'}])},label:{show:true,position:'top',formatter:p=>`¥${Number(p.value).toLocaleString()}`,color:'#dce8ff',fontSize:10},data:props.data.map(x=>Math.max(x.paidAmount,1))},{type:'scatter',symbolSize:12,itemStyle:{color:'#ffc93d',shadowBlur:12,shadowColor:'#ffc93d'},data:props.data.map(x=>Math.max(x.paidAmount,1))}]}));const render=()=>chart.value?.setOption(option.value,true);onMounted(()=>{chart.value=echarts.init(el.value,'warehouse');render();addEventListener('resize',chart.value.resize)});watch(option,render,{deep:true});onBeforeUnmount(()=>chart.value?.dispose())
</script><template><div ref="el" class="chart" role="img" aria-label="历史活跃日支付金额事件柱图，对数刻度"></div></template>
